 if(argc!=5)throw std::runtime_error("expected metallib, damping, steps, x-offset");double damping=std::stod(argv[2]);unsigned steps=std::stoul(argv[3]);double offset=std::stod(argv[4]);std::cout<<std::setprecision(17);
 auto bird=makeCrowArticulatedWingMechanicsFixture(crowHipRollModel());auto&bm=bird.mechanics;bm.world.gravityAndTimestep.x=bm.world.gravityAndTimestep.y=bm.world.gravityAndTimestep.z=0;
 auto rodm=model(9);auto initial=shaped(rodm,delta);for(auto& p:initial.positions)p[0]+=offset;DiscreteElasticRodEnergy initialEnergy;if(!evaluateDiscreteElasticRodEnergy(rodm,initial,initialEnergy).succeeded())throw std::runtime_error("initial energy");
 HeterogeneousRodProgram rod;rod.instanceId="rachis_segment";rod.model=rodm;rod.defaultState=initial;rod.stepConfig.timestep=.001;rod.stepConfig.gravity={0,0,0};rod.stepConfig.solverIterations=4096;rod.stepConfig.constraintTolerance=1e-10;rod.stepConfig.linearDamping=damping;rod.stepConfig.twistDamping=100;rod.collision.enableToolCollision=false;rod.collision.enableCCD=false;rod.attachments={{.nodeIndex=0,.targetPosition={offset,0,0}},{.nodeIndex=4,.targetPosition={offset+L/2,delta,0}},{.nodeIndex=8,.targetPosition={offset+L,0,0}}};rod.rigidBindings.resize(3);
 std::array<HeterogeneousWorldComponent,1>components{{{.model=&bm,.instanceId="v15_crow"}}};std::array<HeterogeneousRodProgram,1>rods{rod};EngineModelComposeConfig cc;cc.name="resident_trajectory_probe";cc.gravityAndTimestep={0,0,0,.001f};HeterogeneousWorld world;auto cd=composeHeterogeneousWorld(components,rods,world,cc);if(!cd.succeeded())throw std::runtime_error("compose: "+cd.message);CompiledWorld compiled;auto co=compileMetalWorld(world,compiled);if(!co.succeeded())throw std::runtime_error("compile: "+co.message);
 std::vector<float>effort(bm.articulations[0].nv,0);MetalWorldBatch batch;batch.environmentCount=1;batch.controlStepCount=1;batch.initialQ=bm.defaultQ;batch.initialV=bm.defaultV;batch.efforts=effort;MetalWorldConfig mc;mc.metallibPath=argv[1];mc.preferParallelABA=false;MetalWorldContext context(mc);MetalWorldStepConfig cfg;cfg.timestepSeconds=.001f;cfg.physicsSubsteps=1;cfg.solverMode=MetalWorldSolverMode::qualityNewton;cfg.applyBodyDamping=false;cfg.captureContactEvidence=true;cfg.publishFinalState=true;
 MetalWorldResidentState resident;bool ok=true;std::cout<<"{\"event\":\"start\",\"damping\":"<<damping<<",\"steps\":"<<steps<<",\"initial_energy\":"<<initialEnergy.total()<<",\"world_fingerprint\":"<<co.fingerprint<<"}"<<std::endl;
 for(unsigned step=0;step<steps;++step){MetalWorldSubmission submission;auto submitted=step==0?context.initializeResidentState(compiled,batch,cfg,resident,submission):context.submitResident(compiled,batch,cfg,resident,submission);if(!submitted.succeeded()||!submission.valid()){std::cout<<"{\"event\":\"failure\",\"step\":"<<step+1<<",\"phase\":\"submit\",\"message\":"<<std::quoted(submitted.message)<<"}"<<std::endl;ok=false;break;}batch.initialQ={};batch.initialV={};MetalWorldResult out;auto d=submission.wait(out);if(!d.succeeded()||!d.published||d.successfulStepCount!=1||d.failedStepCount!=0||out.finalRodNodes.size()!=9||out.finalRodEdges.size()!=8){std::cout<<"{\"event\":\"failure\",\"step\":"<<step+1<<",\"phase\":\"wait\",\"message\":"<<std::quoted(d.message)<<",\"status\":"<<d.firstGPUStatusCode<<",\"steps\":"<<d.successfulStepCount<<",\"failed\":"<<d.failedStepCount<<",\"nodes\":"<<out.finalRodNodes.size()<<"}"<<std::endl;ok=false;break;}
